import builtins, json, struct, time, numpy as np, nuka
def frames(n):
    for _ in range(n):
        app.update(True)
def tick():
    return app.actions.run('timeline.status')['tick']
def step(n):
    t = tick()
    app.actions.run('sim.step', steps=n)
    deadline = time.monotonic() + 60.0
    while tick() < t + n:
        assert time.monotonic() < deadline, tick()
        app.update(True)
    frames(3)
def field(f):
    return np.asarray(app.world.download_field(f), dtype=np.float32).reshape(app.world.env_count, -1)[0].copy()
def state():
    F = nuka.Field
    return (field(F.JOINT_POSITION), field(F.JOINT_VELOCITY), field(F.ARTICULATION_LINK_POSE), field(F.LINK_VELOCITY))
def fails(action, text, **args):
    from nuka.editor.app import ActionError
    try:
        app.actions.run(action, **args)
    except ActionError as e:
        assert text in str(e), (action, args, str(e))
    else:
        raise AssertionError((action, args))
def nkml(path, obs, act, seed):
    rng = np.random.default_rng(seed)
    dims = [obs, 32, act]
    mean = (0.1 * rng.standard_normal(obs)).astype(np.float32)
    std = (0.5 + rng.random(obs)).astype(np.float32)
    layers = []
    with open(path, 'wb') as f:
        f.write(struct.pack('<IIIff', 0x4E4B4D4C, 1, obs, 5.0, 1.0))
        f.write(mean.tobytes() + std.tobytes())
        f.write(struct.pack('<I', 2))
        for l in range(2):
            w = (rng.standard_normal((dims[l + 1], dims[l])) / np.sqrt(dims[l])).astype(np.float32)
            b = (0.3 * rng.standard_normal(dims[l + 1])).astype(np.float32)
            f.write(struct.pack('<III', dims[l], dims[l + 1], 1 - l))
            f.write(w.tobytes() + b.tobytes())
            layers.append((w.astype(np.float64), b.astype(np.float64), 1 - l))
    return mean.astype(np.float64), std.astype(np.float64), layers
def forward(net, obs):
    mean, std, layers = net
    x = np.clip((obs - mean) / std, -5.0, 5.0)
    for w, b, elu in layers:
        x = w @ x + b
        if elu:
            x = np.where(x > 0.0, x, np.expm1(x))
    return x
TERMS = [('base_ang_vel', 3, 0.25), ('projected_gravity', 3, 1.0), ('velocity_commands', 3, 1.0), ('joint_pos_rel', 12, 1.0), ('joint_vel_rel', 12, 0.05), ('last_action', 12, 1.0)]
def contract(stem, joints, dt, **over):
    n = len(joints)
    c = {'version': 1, 'joints': joints, 'default': [0.1 * (-1) ** k for k in range(n)], 'stiffness': [30.0] * n, 'damping': [0.7] * n, 'effort': [20.0] * n, 'armature': 0.0, 'action_scale': 0.25, 'dt': dt, 'decimation': 4, 'history': 3, 'terms': [{'name': t, 'dims': d, 'scale': s} for t, d, s in TERMS], 'command_limit': {}}
    c.update(over)
    with open(stem + '.contract.json', 'w') as f:
        json.dump(c, f)
    return c
def frame(st, last, c, links, root, cmd):
    q, qd, pose, vel = st
    p, v = pose[root * 7:root * 7 + 7].astype(np.float64), vel[root * 6:root * 6 + 6].astype(np.float64)
    w, u, d = p[3], p[4:7], np.array([0.0, 0.0, -1.0])
    g = d * (2.0 * w * w - 1.0) - np.cross(u, d) * w * 2.0 + u * np.dot(u, d) * 2.0
    vals = {'base_ang_vel': v[0:3], 'projected_gravity': g, 'velocity_commands': np.asarray(cmd, np.float64), 'joint_pos_rel': q[links] - np.asarray(c['default']), 'joint_vel_rel': qd[links], 'last_action': last}
    return [vals[t['name']] * t['scale'] for t in c['terms']]
def assemble(history):
    return np.concatenate([np.concatenate([h[k] for h in history]) for k in range(len(history[0]))])
nkml('${out}/go2.bin', 235, 12, 1)
for k, v in dict(frames=frames, tick=tick, step=step, field=field, state=state, fails=fails, nkml=nkml, forward=forward, contract=contract, frame=frame, assemble=assemble).items():
    setattr(builtins, 'pc_' + k, v)
